def apply_guidance_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["GuidanceProgress", "GeneratedPdf"]:
            schema_editor.create_model(apps.get_model("guidance", model_name))

def reverse_guidance_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["GeneratedPdf", "GuidanceProgress"]:
            schema_editor.delete_model(apps.get_model("guidance", model_name))

